let mermaidInitialized = false;

export const ArchitectureDiagram = () => {
  const containerRef = useRef(null);
  const [diagramId] = useState(() => `architecture-diagram-${Math.random().toString(36).slice(2)}`);
  const [error, setError] = useState(false);

  useEffect(() => {
    if (!mermaidInitialized) {
      mermaid.initialize({
        startOnLoad: false,
        theme: "dark",
        securityLevel: "loose",
        themeVariables: {
          primaryColor: "#1f1f2e",
          primaryTextColor: "#ffffff",
          primaryBorderColor: "#4A2FBD",
          lineColor: "#AA367C",
          fontFamily: "Centra, sans-serif",
        },
      });
      mermaidInitialized = true;
    }

    let cancelled = false;

    mermaid
      .render(diagramId, diagramDefinition)
      .then(({ svg }) => {
        if (!cancelled && containerRef.current) {
          containerRef.current.innerHTML = svg;
        }
      })
      .catch(() => {
        if (!cancelled) setError(true);
      });

    return () => { cancelled = true; };
  }, [diagramId]);

  return (
    <div className="architecture-diagram">
      <h4>Project Architecture</h4>
      <p className="architecture-diagram-hint">Click a node to jump to that file on GitHub.</p>
      {error ? (
        <p className="tab-placeholder">Diagram failed to load.</p>
      ) : (
        <div ref={containerRef} className="architecture-diagram-canvas" />
      )}
    </div>
  );
};
